package mediadownload

import (
	"encoding/base64"
)

const (
	genuineMP4VideoBase64    = ``
	genuineMP4AudioBase64    = ``
	genuineWebMVideoBase64   = ``
	genuineWebMAudioBase64   = ``
	genuineOggAudioBase64    = ``
	genuineMPEGTSVideoBase64 = ``
)

func decodeMediaFixture(encoded string) []byte {
	data, err := base64.StdEncoding.DecodeString(encoded)
	if err != nil {
		panic(err)
	}
	return data
}

func genuineMP4VideoBytes() []byte {
	return decodeMediaFixture(genuineMP4VideoBase64)
}

func genuineMP4AudioBytes() []byte {
	return decodeMediaFixture(genuineMP4AudioBase64)
}

func genuineWebMVideoBytes() []byte {
	return decodeMediaFixture(genuineWebMVideoBase64)
}

func genuineWebMAudioBytes() []byte {
	return decodeMediaFixture(genuineWebMAudioBase64)
}

func genuineOggAudioBytes() []byte {
	return decodeMediaFixture(genuineOggAudioBase64)
}

func genuineMPEGTSVideoBytes() []byte {
	return decodeMediaFixture(genuineMPEGTSVideoBase64)
}

func fakeEBMLVideoWithFrame(frame []byte) []byte {
	docType := fakeEBMLElement([]byte{0x42, 0x82}, []byte("webm"))
	header := fakeEBMLElement([]byte{0x1a, 0x45, 0xdf, 0xa3}, docType)
	trackEntry := append(fakeEBMLElement([]byte{0xd7}, []byte{1}), fakeEBMLElement([]byte{0x83}, []byte{1})...)
	trackEntry = append(trackEntry, fakeEBMLElement([]byte{0x86}, []byte("V_VP9"))...)
	tracks := fakeEBMLElement([]byte{0x16, 0x54, 0xae, 0x6b}, fakeEBMLElement([]byte{0xae}, trackEntry))
	block := append([]byte{0x81, 0, 0, 0x80}, frame...)
	clusterPayload := fakeEBMLElement([]byte{0xe7}, []byte{0})
	clusterPayload = append(clusterPayload, fakeEBMLElement([]byte{0xa3}, block)...)
	cluster := fakeEBMLElement([]byte{0x1f, 0x43, 0xb6, 0x75}, clusterPayload)
	segmentPayload := append(tracks, cluster...)
	return append(header, fakeEBMLElement([]byte{0x18, 0x53, 0x80, 0x67}, segmentPayload)...)
}

func fakeEBMLElement(id, payload []byte) []byte {
	if len(payload) >= 0x7f {
		panic("test EBML element too large")
	}
	result := append([]byte(nil), id...)
	result = append(result, byte(0x80|len(payload)))
	return append(result, payload...)
}
